  'about.compareThem2':                   { sk: "6 alebo 12 mesiacov", cs: "6 nebo 12 měsíců", hu: "6 vagy 12 hónap", en: "6 or 12 months", de: "6 oder 12 Monate" },
  'about.compareUs2':                     { sk: "Bez viazanosti", cs: "Bez závazků", hu: "Szerződéses kötöttség nélkül", en: "No commitment", de: "Ohne Bindung" },
