  'pricing.budgetLead1':             { sk: "Okrem našej ceny za správu kampaní potrebujete aj", cs: "Kromě naší ceny za správu kampaní potřebujete také", hu: "A kampánykezelési díjunkon felül szüksége van", en: "In addition to our campaign management fee, you also need", de: "Zusätzlich zu unserem Verwaltungspreis benötigen Sie auch ein" },
  'pricing.budgetLead2':             { sk: "reklamný rozpočet (budget)", cs: "reklamní rozpočet (budget)", hu: "hirdetési költségvetésre (budget)", en: "an ad budget", de: "Werbebudget" },
  'pricing.budgetLead3':             { sk: "— peniaze, ktoré platíte priamo Facebooku alebo Google za zobrazovanie vašich reklám. Tento rozpočet si nastavujete vy podľa svojich možností. Čím viac investujete, tým viac ľudí oslovíte.", cs: "— peníze, které platíte přímo Facebooku nebo Googlu za zobrazování vašich reklam. Tento rozpočet si nastavujete vy podle svých možností. Čím více investujete, tím více lidí oslovíte.", hu: "— pénz, amelyet közvetlenül a Facebooknak vagy a Google-nak fizet a hirdetései megjelenítéséért. Ezt a költségvetést Ön határozza meg a lehetőségei szerint. Minél többet fektet be, annál több embert ér el.", en: "— money you pay directly to Facebook or Google to show your ads. You set this budget yourself based on what you can afford. The more you invest, the more people you reach.", de: "— Geld, das Sie direkt an Facebook oder Google für die Anzeige Ihrer Werbung zahlen. Sie legen dieses Budget selbst nach Ihren Möglichkeiten fest. Je mehr Sie investieren, desto mehr Menschen erreichen Sie." },
  'pricing.budgetMonth':             { sk: "/MESIAC", cs: "/MĚSÍC", hu: "/HÓNAP", en: "/MONTH", de: "/MONAT" },
  'pricing.budget1Plan':             { sk: "Starter / Pro", cs: "Starter / Pro", hu: "Starter / Pro", en: "Starter / Pro", de: "Starter / Pro" },
  'pricing.budget1Desc':             { sk: "Pre živnostníkov a malé firmy. Test kampaní, prvé výsledky, overenie potenciálu.", cs: "Pro živnostníky a malé firmy. Test kampaní, první výsledky, ověření potenciálu.", hu: "Egyéni vállalkozóknak és kisvállalkozásoknak. Kampánytesztelés, első eredmények, a potenciál igazolása.", en: "For sole traders and small businesses. Campaign testing, first results, validating potential.", de: "Für Einzelunternehmer und kleine Firmen. Kampagnentests, erste Ergebnisse, Potenzialprüfung." },
  'pricing.budget2Plan':             { sk: "Pro / Enterprise", cs: "Pro / Enterprise", hu: "Pro / Enterprise", en: "Pro / Enterprise", de: "Pro / Enterprise" },
  'pricing.budget2Desc':             { sk: "Pre stabilnejšie výsledky. Viacero kampaní paralelne, lepšie testovanie, väčší dosah.", cs: "Pro stabilnější výsledky. Více kampaní paralelně, lepší testování, větší dosah.", hu: "Stabilabb eredményekért. Több kampány párhuzamosan, jobb tesztelés, nagyobb elérés.", en: "For more stable results. Multiple parallel campaigns, better testing, broader reach.", de: "Für stabilere Ergebnisse. Mehrere parallele Kampagnen, besseres Testen, größere Reichweite." },
  'pricing.budget3Plan':             { sk: "Premium", cs: "Premium", hu: "Premium", en: "Premium", de: "Premium" },
  'pricing.budget3Desc':             { sk: "Pre veľké projekty s maximálnym dosahom. Plný škálovaný marketing s remarketingom.", cs: "Pro velké projekty s maximálním dosahem. Plně škálovaný marketing s remarketingem.", hu: "Nagy projektekhez maximális eléréssel. Teljesen skálázott marketing remarketinggel.", en: "For large projects with maximum reach. Fully scaled marketing with remarketing.", de: "Für große Projekte mit maximaler Reichweite. Voll skaliertes Marketing mit Remarketing." },
