  'pricing.oneoff2Title':            { sk: "Google Analytics + tag manager setup", cs: "Google Analytics + tag manager setup", hu: "Google Analytics + tag manager beállítás", en: "Google Analytics + Tag Manager setup", de: "Google Analytics + Tag Manager Setup" },
  'pricing.oneoff2Desc':             { sk: "Kompletný setup analytiky vrátane pokročilého sledovania e-shopu a pokročilého GTM.", cs: "Kompletní setup analytiky včetně pokročilého sledování e-shopu a pokročilého GTM.", hu: "Az elemzések teljes beállítása, beleértve a webshop fejlett követését és a haladó GTM-et.", en: "Complete analytics setup including advanced e-shop tracking and advanced GTM.", de: "Komplette Analytics-Einrichtung einschließlich erweitertem E-Shop-Tracking und erweitertem GTM." },
